grid(min: 22rem) {
    card(root board.Board, count: (root board.Board).cards.count(c -> c.column.title != "Done")) {
        list((root board.Board).cards.filter(c -> c.column.title != "Done")) { c ->
            row(c)
        }
    }
    card(todo.todos, count: todo.todos.items.count(t -> not t.done)) {
        list(todo.todos.items.filter(t -> not t.done)) { t ->
            row(t)
        }
    }
    card(chat.conversations, count: 1) {
        list(chat.conversations.filter(c -> c.title == "Release checklist")) { c ->
            row(c)
        }
    }
}
